rule YARA_CobaltStrike_Generic {
    meta:
        description = "Detect generic Cobalt Strike Beacon patterns"
        author = "SOC Team"
        false_positive_exceptions = "Signed Microsoft binaries"
    strings:
        $a = { 4D 5A ?? ?? ?? 00 00 00 00 00 00 00 }
        $b = "CobaltStrike"
    condition:
        // Original condition: any of them
        // Updated: require presence and exclude if signed by Microsoft Authenticode thumbprint 3A7B..C9F2
        (any of ($a, $b)) and not pe.authenticode.thumbprint == "3A7B...C9F2"
}

